import cyclopts


def status():
    """Show service status."""
    print("Service status: running")


app = cyclopts.App(default=status)


@app.command
def start():
    """Start the service."""
    print("Service started")


@app.command
def stop():
    """Stop the service."""
    print("Service stopped")


if __name__ == "__main__":
    app()
